@startuml

class Client {
  +nin : string
  +tin : string
  +name : string
  +address : string
}

class BicycleModel {
  +name : string
  +type : string
  +gears : int
}

class Bicycle {
  +id : string
}

class Store {
  +name : string
  +address : string
}

class Reservation {
  +pickup_day : date
}

class Rental {
  +return_date : date
}

Client "1" -- "*" Reservation : makes
Reservation "*" -- "1" BicycleModel : requests
Reservation "*" -- "1" Store : at
Reservation "1" -- "0..1" Rental : results in
Rental "*" -- "1" Bicycle : uses
Rental "*" -- "1" Store : at

@enduml

